58	    // The project each conversation starts from, with its current plate sliced.
59	    // `plate_type` (a curr_bed_type value, such as "Cool Plate") is the plate
60	    // the person selected in the sidebar before the slice. A new project
61	    // keeps the plate selected last (the prepare conversation's printer setup
62	    // selects the Textured PEI Plate), so every conversation names its own,
63	    // and a run of some conversations gets the plates a full run does.
64	    bool prompt_fixture(const std::string& kind, const std::string& name, const std::string& plate_type)
65	    {
66	        using namespace std::chrono_literals;
67	        // A slice the last conversation's model started may still be running.
68	        // When it ends the app starts a turn about it in that conversation;
69	        // that turn is answered with nothing, so this one starts clean.
70	        wait_for([this] { return !m_plater->is_background_process_slicing(); }, 120s);
71	        wait_for([] { return !g_held_model_requests.empty(); }, 2s);
72	        while (!g_held_model_requests.empty()) {
73	            HeldModelRequest request = std::move(g_held_model_requests.front());
74	            g_held_model_requests.pop_front();
75	            prompt_answer(request, nlohmann::json::array(), "");
76	            wait_for([this] { return !g_held_model_requests.empty() || !project_host().busy(); }, 10s);
77	        }
78	        prompt_restore_settings(name);
79	        if (kind == "overhang") {
80	            // print_issues_scenario's slab on one leg: slicing it warns.
81	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_new_project");
82	            const std::string cube = std::string(JUSPRIN_SOURCE_DIR) + "/tests/data/test_stl/ASCII/20mmbox-LF.stl";
83	            const auto strategy = LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence;
84	            check(m_plater->load_files(std::vector<boost::filesystem::path>{cube}, strategy, false).size() == 1, name + "_cube_loaded");
85	            check(m_plater->load_files(std::vector<boost::filesystem::path>{write_overhang_stl()}, strategy, false).size() == 1,
86	                  name + "_overhang_loaded");
87	            PartPlateList& plates = m_plater->get_partplate_list();
88	            check(plates.get_plate(0)->add_instance(0, 0, true) == 0, name + "_cube_centred");
89	            check(plates.get_plate(0)->add_instance(1, 0, true) == 0, name + "_overhang_centred");
90	            m_plater->canvas3D()->reload_scene(true, true);
91	            move_object(1, Vec3d(70, 0, 0));
92	        } else if (kind == "single") {
93	            // One box on one plate, as a person who just added a model has.
94	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_new_project");
95	            const std::string cube = std::string(JUSPRIN_SOURCE_DIR) + "/tests/data/test_stl/ASCII/20mmbox-LF.stl";
96	            const auto strategy = LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence;
97	            check(m_plater->load_files(std::vector<boost::filesystem::path>{cube}, strategy, false).size() == 1, name + "_cube_loaded");
98	            check(m_plater->get_partplate_list().get_plate(0)->add_instance(0, 0, true) == 0, name + "_cube_centred");
99	            m_plater->canvas3D()->reload_scene(true, true);
100	        } else {
101	            load_multi_plate_fixture();
102	        }
103	        check(!plate_type.empty(), name + "_names_its_plate");
104	        if (!plate_type.empty()) {
105	            // Selected only when it differs: selecting the plate already
106	            // selected still marks every plate on it unsliced.
107	            ConfigOptionEnum<BedType> plate;
108	            const bool known = plate.deserialize(plate_type);
109	            check(known, name + "_plate_type_known");
110	            if (known && wxGetApp().preset_bundle->project_config.opt_enum<BedType>("curr_bed_type") != plate.value)
111	                check(SetupCommands::select_bed_type(*m_plater, int(plate.value)), name + "_plate_selected");
112	        }
113	        const auto slice = [this](std::chrono::seconds limit) {
114	            wait_for([this] { return !m_plater->is_background_process_update_scheduled(); }, 10s);
115	            installed_shell()->status_row()->request_slice();
116	            return wait_for([this] {
117	                const auto* plate = m_plater->get_partplate_list().get_curr_plate();
118	                return plate && plate->is_slice_result_valid() && !m_plater->is_background_process_slicing();
119	            }, limit);
120	        };
121	        const bool sliced = slice(60s) || slice(120s);
122	        if (!sliced) {
123	            issue_monitor().refresh_now();
124	            for (const auto& issue : issues().issues)
125	                std::cerr << "HARNESS PROMPT " << name << " fixture issue " << issue.id << " '" << issue.message << "'\n";
126	        }
127	        check(sliced, name + "_fixture_sliced");
128	        installed_shell()->status_row()->request_prepare();
129	        wait_for([this] { return m_notebook->GetSelectedPageName() == TAB_ID_PREPARE && !m_plater->is_preview_shown(); }, 20s);
130	
131	        Agent::AgentHost& host = project_host();
132	        if (!host.conversation().empty())
133	            host.on_page_message(nlohmann::json{{"protocol", Agent::Protocol::kName},
134	                                                {"version", Agent::Protocol::kVersion},
135	                                                {"id", "prompt-new-" + name},
136	                                                {"type", Agent::Protocol::kCreateConversation},
137	                                                {"payload", nlohmann::json::object()}}
138	                                     .dump());
139	        const bool fresh = wait_for([&host] { return host.conversation().empty() && !host.busy(); }, 10s);
140	        check(fresh, name + "_starts_an_empty_chat");
141	        return sliced && fresh;
142	    }
