150	    // Copies the source tree's `from` to prompt_model_path(`as`).
151	    bool prompt_copy_model(const nlohmann::json& copy, const std::string& name)
152	    {
153	        const fs::path target = prompt_model_path(copy.at("as").get<std::string>());
154	        boost::system::error_code error;
155	        fs::create_directories(target.parent_path(), error);
156	        fs::copy_file(fs::path(JUSPRIN_SOURCE_DIR) / copy.at("from").get<std::string>(), target,
157	                      fs::copy_options::overwrite_existing, error);
158	        check(!error, name + "_model_copied");
159	        return !error;
160	    }
