162	    // The page's skills the recorder checks for, as the page sends each one:
163	    // the SKILL.md body (skillParser.ts). Only the file-loaded skill brings
164	    // a picture of the plate.
165	    static constexpr const char* kPromptFileLoadedSkill = "file-loaded";
166	    static const std::vector<std::string>& prompt_skill_names()
167	    {
168	        static const std::vector<std::string> names{kPromptFileLoadedSkill, "print-issues", "project-setup-changed",
169	                                                     "slice-failed"};
170	        return names;
