172	    static std::string prompt_skill_text(const std::string& name)
173	    {
174	        std::ifstream file((fs::path(JUSPRIN_SOURCE_DIR) / "src/slic3r/GUI/JusPrin/AgentUI/src/skills" / name / "SKILL.md").string(),
175	                           std::ios::binary);
176	        std::string text((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
177	        // A Windows checkout has CRLF; the page sends the skill with LF.
178	        text.erase(std::remove(text.begin(), text.end(), '\r'), text.end());
179	        const std::size_t body = text.find("\n---\n");
180	        text = body == std::string::npos ? std::string() : text.substr(body + 5);
181	        text.erase(0, text.find_first_not_of('\n'));
182	        text.erase(text.find_last_not_of(" \n") + 1);
183	        return text;
184	    }
