186	    // Which skill an input item is (a developer item that starts with its
187	    // text), or empty; and whether it is a plate picture (a user item
188	    // holding one image and nothing else).
189	    static std::string prompt_skill_of(const nlohmann::json& item)
190	    {
191	        if (item.value("role", "") != "developer" || !item.contains("content") || !item["content"].is_string())
192	            return {};
193	        for (const std::string& name : prompt_skill_names()) {
194	            const std::string text = prompt_skill_text(name);
195	            if (!text.empty() && item["content"].get<std::string>().rfind(text, 0) == 0)
196	                return name;
197	        }
198	        return {};
199	    }
200	    static bool prompt_is_picture(const nlohmann::json& item)
201	    {
202	        return item.value("role", "") == "user" && item.contains("content") && item["content"].is_array() &&
203	               item["content"].size() == 1 && item["content"][0].value("type", "") == "input_image";
204	    }
205	    // The skills and the number of pictures among a request's last
206	    // `appended` items. A chat's requests repeat its record and append to it
207	    // (ba08e2c18f), and on the Responses API a fired skill stays in that
208	    // record: nothing hides it after its own request (fe70eea593). So a
209	    // skill "sent once" is one appended once, on the request that fired it,
210	    // and replayed unchanged as history after that.
211	    static std::pair<std::vector<std::string>, std::size_t> prompt_appended_skills(const nlohmann::json& input,
212	                                                                                   std::size_t appended)
213	    {
214	        std::pair<std::vector<std::string>, std::size_t> found;
215	        for (std::size_t i = input.size() - appended; i < input.size(); ++i) {
216	            if (const std::string skill = prompt_skill_of(input[i]); !skill.empty())
217	                found.first.push_back(skill);
218	            found.second += prompt_is_picture(input[i]) ? 1 : 0;
219	        }
220	        return found;
221	    }
