223	    // "{{file/<name>}}" is the path of a model a step copied under that name;
224	    // "{{attachment}}" the id of the file the person last attached;
225	    // "{{result/<pointer>}}" is the last tool result in this request;
226	    // "{{workspace/sessionId}}", "{{workspace/revision}}", "{{workspace/plateId/N}}" (the Nth plate),
227	    // "{{workspace/activePlateId}}", "{{workspace/firstObjectId}}" (the
228	    // active plate's first object), "{{workspace/filamentPreset}}" and
229	    // "{{workspace/printerPreset}}" the project now; "{{object}}" the object
230	    // an "eachObject" answer is being read for, "{{plate}}" the plate an
231	    // "eachPlate" answer is being read for.
232	    nlohmann::json prompt_fill(const nlohmann::json& value, const nlohmann::json& body, const std::string& name)
233	    {
234	        using nlohmann::json;
235	        if (value.is_object() || value.is_array()) {
236	            json filled = value;
237	            for (auto& [key, item] : filled.items())
238	                item = prompt_fill(item, body, name);
239	            return filled;
240	        }
241	        if (!value.is_string())
242	            return value;
243	        const std::string text = value;
244	        if (text.size() < 5 || text.rfind("{{", 0) != 0 || text.compare(text.size() - 2, 2, "}}") != 0)
245	            return value;
246	        const std::string path = text.substr(2, text.size() - 4);
247	        if (path == "object" && !m_prompt_object.empty())
248	            return m_prompt_object;
249	        if (path == "plate" && !m_prompt_plate.empty())
250	            return m_prompt_plate;
251	        if (path.rfind("file/", 0) == 0)
252	            return prompt_model_path(path.substr(5));
253	        if (path == "attachment" && !m_prompt_attachment.empty())
254	            return m_prompt_attachment;
255	        if (path == "workspace/sessionId")
256	            return std::to_string(installed_shell()->workspace()->snapshot().session.value());
257	        if (path == "workspace/revision")
258	            return installed_shell()->workspace()->snapshot().revision;
259	        if (path == "workspace/filamentPreset")
260	            return installed_shell()->workspace()->snapshot().setup.filament_preset;
261	        if (path == "workspace/printerPreset")
262	            return installed_shell()->workspace()->snapshot().setup.printer_preset;
263	        if (path.rfind("workspace/plateId/", 0) == 0) {
264	            const auto plates = installed_shell()->workspace()->snapshot().plates;
265	            const std::size_t number = std::stoul(path.substr(18));
266	            if (number >= 1 && number <= plates.size())
267	                return std::to_string(plates[number - 1].id.value());
268	        }
269	        if (path == "workspace/activePlateId" || path == "workspace/firstObjectId")
270	            for (const auto& plate : installed_shell()->workspace()->snapshot().plates)
271	                if (plate.active && (path == "workspace/activePlateId" || !plate.objects.empty()))
272	                    return std::to_string(path == "workspace/activePlateId" ? plate.id.value() : plate.objects.front().id.value());
273	        if (path.rfind("result/", 0) == 0) {
274	            const json& input = body.at("input");
275	            for (auto item = input.rbegin(); item != input.rend(); ++item)
276	                if (item->value("type", "") == "function_call_output") {
277	                    const json output = json::parse(item->at("output").get<std::string>());
278	                    const json::json_pointer pointer(path.substr(6));
279	                    if (output.contains("result") && output["result"].contains(pointer))
280	                        return output["result"][pointer];
281	                    break;
282	                }
283	        }
284	        check(false, name + "_fills " + text);
285	        return value;
286	    }
