288	    // Answers a held request with model output, as the service streams it.
289	    static void prompt_answer(HeldModelRequest& request, const nlohmann::json& output, const std::string& text)
290	    {
291	        using Event = Agent::AgentHttpEvent;
292	        const auto frame = [](const nlohmann::json& event) { return "event: message\ndata: " + event.dump() + "\n\n"; };
293	        if (!text.empty())
294	            request.answer(Event{Event::Kind::Data, frame({{"type", "response.output_text.delta"}, {"delta", text}}), {}, 0});
295	        request.answer(Event{Event::Kind::Data,
296	                             frame({{"type", "response.completed"}, {"response", {{"output", output}}}}), {}, 0});
297	        request.answer(Event{Event::Kind::Complete, {}, {}, 200});
298	    }
