300	    // The next request of this turn the model is asked, past any chat title.
301	    std::optional<HeldModelRequest> prompt_next_request()
302	    {
303	        for (;;) {
304	            if (!wait_for([] { return !g_held_model_requests.empty(); }, std::chrono::seconds(120)))
305	                return std::nullopt;
306	            HeldModelRequest request = std::move(g_held_model_requests.front());
307	            g_held_model_requests.pop_front();
308	            if (request.body.contains("tools"))
309	                return request;
310	            prompt_answer(request, nlohmann::json::array({{{"type", "message"}, {"role", "assistant"},
311	                                                           {"content", nlohmann::json::array({{{"type", "output_text"},
312	                                                                                               {"text", "Fixture chat"}}})}}}),
313	                          "Fixture chat");
314	        }
315	    }
