324	    // The person attaches a copied model to the chat, as the composer's file
325	    // picker does; its id, once the app has stored it, or empty.
326	    std::string prompt_attach(const nlohmann::json& copy, const std::string& name)
327	    {
328	        if (!prompt_copy_model(copy, name))
329	            return {};
330	        std::ifstream file(prompt_model_path(copy.at("as").get<std::string>()), std::ios::binary);
331	        const std::string bytes((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
332	        static int next = 0;
333	        const std::string client_id = "prompt-attachment-" + std::to_string(++next);
334	        Agent::AgentHost& host = project_host();
335	        host.on_page_message(nlohmann::json{{"protocol", Agent::Protocol::kName},
336	                                            {"version", Agent::Protocol::kVersion},
337	                                            {"id", "prompt-attach-" + std::to_string(next)},
338	                                            {"type", Agent::Protocol::kAttachFile},
339	                                            {"payload", {{"clientAttachmentId", client_id},
340	                                                         {"name", copy.at("as").get<std::string>()},
341	                                                         {"source", "picker"},
342	                                                         {"dataBase64", wxBase64Encode(bytes.data(), bytes.size()).utf8_string()}}}}
343	                                 .dump());
344	        const auto record = persistence().document().find_attachment_by_client_id(client_id);
345	        check(record.has_value() && record->kind == "model", name + "_model_attached");
346	        return record ? record->id : std::string();
347	    }
