349	    // The answers' reads called after the kept request, in the same turn;
350	    // returns each with the result the app gave, as the model would read it.
351	    // A read marked "eachObject" is called once for every object on every
352	    // plate, and an "allSettings" entry with it once for every object; one
353	    // marked "eachPlate" once for every plate. A read whose result brings a
354	    // picture (view_render) keeps the result's text only.
355	    // An "allSettings" entry reads every setting of its scope:
356	    // the keys come from the app's own settings_search (an empty query lists
357	    // them all, page by page; those pages are not kept), then settings_get
358	    // reads them 32 at a time. With "keysOf" it reads, under its scope, the
359	    // keys of the scopes named, read before it, that are not its own: how
360	    // the app answers a name asked for under the wrong scope. The workspace block every result
361	    // carries is kept once, beside them, and left out of each result that
362	    // repeats it exactly.
363	    nlohmann::json prompt_answers(const std::string& name, HeldModelRequest request, const nlohmann::json& script_reads)
364	    {
365	        using nlohmann::json;
366	        json answers = json::array();
367	        int  calls   = 0;
368	        const json kept = request.body.at("input");
369	        // One read in the turn; the result as the app gave it, or nothing.
370	        const auto call = [&](const std::string& tool, const json& arguments) -> std::optional<std::string> {
371	            const std::string call_id = "call_" + name + "_answer_" + std::to_string(++calls);
372	            prompt_answer(request, json::array({{{"type", "function_call"}, {"call_id", call_id}, {"name", tool},
373	                                                 {"arguments", arguments.dump()}}}), "");
374	            std::optional<HeldModelRequest> next = prompt_next_request();
375	            check(next.has_value(), name + "_answer_" + tool + "_returned");
376	            if (!next)
377	                return std::nullopt;
378	            request = std::move(*next);
379	            if (calls == 1) {
380	                // The next request repeats the kept one whole, its skill and
381	                // picture included, and appends neither again (see
382	                // prompt_appended_skills).
383	                const json& input = request.body.at("input");
384	                const bool repeats = input.size() >= kept.size() && std::equal(kept.begin(), kept.end(), input.begin());
385	                check(repeats, name + "_repeats_all_on_the_next_request");
386	                const auto [skills, pictures] = prompt_appended_skills(input, repeats ? input.size() - kept.size() : input.size());
387	                check(skills.empty() && pictures == 0, name + "_skill_and_picture_not_appended_on_the_next_request");
388	            }
389	            // The call's own result: a picture the call returned comes after
390	            // it, as a message of its own, and is not kept.
391	            const json& sent = request.body.at("input");
392	            const auto result = std::find_if(sent.rbegin(), sent.rend(), [&call_id](const json& item) {
393	                return item.value("type", "") == "function_call_output" && item.value("call_id", "") == call_id;
394	            });
395	            check(result != sent.rend(), name + "_answer_" + tool + "_has_its_result");
396	            if (result == sent.rend())
397	                return std::nullopt;
398	            const std::string output = result->at("output");
399	            const json parsed = json::parse(output);
400	            // A slice report, or a read of the slicing section, made while
401	            // this point's own slice runs is answered "busy"
402	            // (refuse_slice_poll): that is the app's answer at this point, and
403	            // the one the model gets.
404	            const bool busy_slicing = (tool == "workspace_inspect" || tool == "slice_report") && parsed.value("state", "") == "failed" &&
405	                                      parsed.contains("error") && parsed.at("error").value("code", "") == "busy";
406	            const bool answered = parsed.value("state", "") == "succeeded" || busy_slicing;
407	            check(answered, name + "_answer_" + tool + "_succeeded");
408	            return answered ? std::optional<std::string>(output) : std::nullopt;
409	        };
410	        std::map<std::string, std::vector<std::string>> scope_keys;
411	        bool ok = true;
412	        for (const json& read : script_reads) {
413	            if (!ok)
414	                break;
415	            std::vector<std::string> objects{std::string()};
416	            if (read.value("eachObject", false)) {
417	                objects.clear();
