511	    // One step of a conversation: what the person does, then the model's
512	    // scripted outputs, one per request the app sends, until they run out.
513	    // The record point numbered `target` is kept, with its answers, and ends
514	    // the conversation (2); otherwise 1, or 0 on a failure.
515	    int prompt_step(const std::string& name, const nlohmann::json& step, nlohmann::json& recorded,
516	                    const nlohmann::json& tools, const std::string& instructions, const nlohmann::json& reads,
517	                    int& point, int target)
518	    {
519	        using nlohmann::json;
520	        using namespace std::chrono_literals;
521	        Agent::AgentHost& host = project_host();
522	        const json        scripted = step.value("replies", json::array());
523	        std::deque<json>  replies(scripted.begin(), scripted.end());
524	
525	        // A person answers seconds later, after OrcaSlicer has taken in the
526	        // last turn's changes: a filament switched by printer_setup leaves
527	        // the plate's slice current until Orca's scheduled update runs.
528	        wait_for([this] { return !m_plater->is_background_process_update_scheduled(); }, 5s);
529	        if (step.contains("copy"))
530	            prompt_copy_model(step["copy"], name);
531	        json attached = json::array();
532	        if (step.contains("attach")) {
533	            m_prompt_attachment = prompt_attach(step["attach"], name);
534	            if (!m_prompt_attachment.empty())
535	                attached.push_back(m_prompt_attachment);
536	        }
537	        if (step.contains("slice")) {
538	            // The person presses Slice (true) or Slice all ("all") in the
539	            // status row, and waits for whatever OrcaSlicer does with it.
540	            // Neither is enabled for a plate OrcaSlicer's check has refused;
541	            // Slice all slices plate by plate and is refused at such a plate.
542	            installed_shell()->status_row()->request_slice(step["slice"] == "all");
543	            wait_for([this] { return !m_plater->is_background_process_slicing(); }, 120s);
544	            const auto snapshot = installed_shell()->workspace()->snapshot();
545	            for (const auto& plate : snapshot.plates)
546	                std::cerr << "HARNESS PROMPT " << name << " pressed Slice: plate " << plate.id.value() << " sliced=" << plate.sliced << " failure='"
547	                              << (plate.slice_failure ? plate.slice_failure->message : std::string()) << "'\n";
548	        }
549	        if (step.contains("say")) {
550	            std::string said = step["say"];
551	            for (std::size_t at; (at = said.find("{{file/")) != std::string::npos;) {
552	                const std::size_t end = said.find("}}", at);
553	                said.replace(at, end + 2 - at, prompt_model_path(said.substr(at + 7, end - at - 7)));
554	            }
555	            static int next = 0;
556	            ++next;
557	            host.on_page_message(json{{"protocol", Agent::Protocol::kName},
558	                                      {"version", Agent::Protocol::kVersion},
559	                                      {"id", "prompt-" + std::to_string(next)},
560	                                      {"type", Agent::Protocol::kUserMessage},
561	                                      {"payload", {{"clientMessageId", "prompt-c-" + std::to_string(next)}, {"text", said},
562	                                                   {"attachmentIds", attached}}}}
563	                                     .dump());
564	        } else if (step.contains("issue")) {
565	            // A setting typed in by hand, the issue OrcaSlicer reports for
566	            // it, and a press of one of the issue's two buttons.
567	            prompt_hand_edit(step.at("set"));
568	            const std::string setting = step.at("set").begin().key();
569	            std::string       issue_id;
570	            wait_for([&] {
571	                issue_monitor().refresh_now();
572	                for (const auto& issue : issues().issues)
573	                    if (issues().checked && issue.source == PrintIssues::IssueSource::Validation && issue.setting == setting)
574	                        issue_id = issue.id;
575	                return !issue_id.empty();
576	            }, 30s);
577	            check(!issue_id.empty(), name + "_issue_reported");
578	            const std::string outcome = issue_id.empty() ? "" : installed_shell()->submit_issue(issue_id, step["issue"]).outcome;
579	            std::cerr << "HARNESS PROMPT " << name << " issue " << issue_id << " outcome=" << outcome << '\n';
580	            check(outcome == "started", name + "_issue_sent_to_the_chat");
581	        } else if (step.contains("drop")) {
582	            // A model with a name that says nothing about it, imported by the
583	            // person into an empty project.
584	            check(prompt_copy_model(json{{"from", step.at("model")}, {"as", step["drop"]}}, name), name + "_model_ready");
585	            check(m_plater->new_project(true, true) != wxID_CANCEL, name + "_empty_project");
