587	        } else if (step.contains("open")) {
588	            // A project someone saved with an author note in its description,
589	            // written by the app's own exporter, then opened.
590	            if (!m_plater->model().model_info)
591	                m_plater->model().model_info = std::make_shared<ModelInfo>();
592	            m_plater->model().model_info->description = step.value("description", "");
593	            const fs::path file = fs::path(data_dir()) / (step["open"].get<std::string>() + ".3mf");
