600	        bool expect_failure = false;
601	        int  calls          = 0;
602	        for (;;) {
603	            // The chat title is asked for after a reply ends; no case reads it.
604	            wait_for([&] { return !g_held_model_requests.empty() || (replies.empty() && !host.busy()); }, 120s);
605	            if (g_held_model_requests.empty()) {
606	                if (!replies.empty()) {
