608	                    std::cerr << "HARNESS PROMPT " << name << " waiting: slicing.running=" << snapshot.slicing.running
609	                              << " orca_slicing=" << m_plater->is_background_process_slicing();
610	                    for (const auto& plate : snapshot.plates)
611	                        std::cerr << " plate " << plate.id.value() << " active=" << plate.active << " sliced=" << plate.sliced;
612	                    issue_monitor().refresh_now();
613	                    for (const auto& issue : issues().issues)
