632	            const bool        appends  = last.is_null() || (input.size() >= last.size() && std::equal(last.begin(), last.end(), input.begin()));
633	            const std::size_t appended = appends ? input.size() - (last.is_null() ? 0 : last.size()) : input.size();
634	            last                       = input;
635	            if (!input.empty() && input.back().value("type", "") == "function_call_output") {
636	                const json output = json::parse(input.back().at("output").get<std::string>());
637	                const std::string state = output.value("state", "");
638	                std::cerr << "HARNESS PROMPT " << name << " result state=" << state
639	                          << (output.contains("error") ? " error=" + output["error"].value("code", "") : std::string()) << '\n';
640	                check((state == "failed") == expect_failure && state != "running", name + "_call_" + std::to_string(calls) + "_outcome");
641	            }
642	            if (replies.empty()) {
643	                check(false, name + "_unscripted_request");
644	                prompt_answer(request, json::array(), "");
645	                continue;
646	            }
647	            const json reply = replies.front();
648	            replies.pop_front();
649	            if (reply.contains("set"))
650	                prompt_hand_edit(reply["set"]);
651	            if (reply.contains("record") && point++ == target) {
652	                // The suite sends its own copies; they must be what the app sends.
653	                const std::string case_name = reply["record"];
654	                // Every request of the project chat offers the same tools,
655	                // whatever its message attaches, then the provider's own
656	                // search, which the suite adds itself (web_search()).
657	                json offered = tools;
658	                offered.push_back(json{{"type", "web_search"}});
659	                check(request.body.at("tools") == offered, case_name + "_tools_match_project_tools_json");
660	                check(request.body.at("instructions") == instructions, case_name + "_instructions_are_the_page_prompt");
661	                json kept = request.body;
662	                kept.erase("tools");
663	                kept.erase("instructions");
664	                // Names this run's project and chat, which the suite's own
665	                // requests are not.
666	                kept.erase("prompt_cache_key");
667	                const std::size_t items = input.size();
668	                // A point marked "skill" is the request where the model first
669	                // reads about that skill's event: it appends that skill, and
670	                // the plate's picture for the file-loaded skill. No other
671	                // point appends a skill or a picture, though it may replay
672	                // one an earlier request appended (prompt_appended_skills),
673	                // and an import's point appends the file-loaded skill alone.
674	                const std::string wanted   = reply.value("skill", "");
675	                const bool        pictured = wanted == kPromptFileLoadedSkill;
