715	    void record_prompt_requests()
716	    {
717	        using nlohmann::json;
718	        m_state->deadline = std::chrono::steady_clock::now() + std::chrono::minutes(30);
719	        const auto read = [](const fs::path& path) {
720	            std::ifstream file(path.string(), std::ios::binary);
721	            return std::string((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
722	        };
723	        const json script = json::parse(read(m_state->prompt_script), nullptr, false);
724	        const json tools  = json::parse(read(fs::path(JUSPRIN_SOURCE_DIR) / "tests/project_prompt/project_tools.json"), nullptr, false);
725	        std::string instructions =
726	            read(fs::path(JUSPRIN_SOURCE_DIR) / "src/slic3r/GUI/JusPrin/AgentUI/src/projectInstructions.fixture.txt");
727	        // A Windows checkout has CRLF; the page sends the prompt with LF.
728	        instructions.erase(std::remove(instructions.begin(), instructions.end(), '\r'), instructions.end());
729	        check(script.is_object() && script.contains("conversations"), "prompt_script_read");
730	        check(tools.is_array() && !instructions.empty(), "prompt_tools_and_instructions_read");
731	        for (const std::string& skill : prompt_skill_names())
732	            check(!prompt_skill_text(skill).empty(), "prompt_skill_text_read_" + skill);
733	        json recorded = json::object();
734	        const json reads = script.is_object() ? script.value("answers", json::array()) : json::array();
735	        bool ok = script.is_object() && tools.is_array();
736	        if (ok)
737	            for (const json& conversation : script["conversations"]) {
738	                const std::string name = conversation.at("name");
739	                int points = 0;
740	                for (const json& step : conversation.at("steps"))
741	                    for (const json& reply : step.value("replies", json::array()))
742	                        points += reply.contains("record") ? 1 : 0;
743	                // One pass per kept request: its answers end the conversation.
744	                for (int target = 0; ok && target < points; ++target) {
745	                    std::cerr << "HARNESS PROMPT conversation " << name << " point " << target << '\n';
746	                    if (!(ok = prompt_fixture(conversation.value("fixture", "plates"), name, conversation.value("plateType", ""))))
747	                        break;
748	                    m_prompt_chat_input.clear();
749	                    int point = 0, result = 1;
750	                    for (const json& step : conversation.at("steps"))
751	                        if (result == 1)
752	                            result = prompt_step(name, step, recorded, tools, instructions, reads, point, target);
753	                    check(result == 2, name + "_point_" + std::to_string(target) + "_kept");
754	                    ok = result == 2;
755	                }
756	                if (!ok)
757	                    break;
758	            }
759	        // The setting items of settings_get and settings_search results repeat
760	        // across reads and points: each distinct one is kept once, in
761	        // settingItems, and a result holds its index there instead.
762	        json items = json::array();
763	        std::map<std::string, std::size_t> index;
764	        for (auto& [case_name, kept] : recorded.items())
765	            for (json& answer : kept["answers"]) {
766	                if (answer["tool"] != "settings_get" && answer["tool"] != "settings_search")
767	                    continue;
768	                json output = json::parse(answer["output"].get<std::string>());
769	                for (const char* field : {"items", "unknownKeys"}) {
770	                    if (!output["result"].contains(field))
771	                        continue;
772	                    for (json& item : output["result"][field]) {
773	                        const auto [found, added] = index.emplace(item.dump(), items.size());
774	                        if (added)
775	                            items.push_back(item);
776	                        item = found->second;
777	                    }
778	                }
779	                answer["output"]       = output.dump();
780	                answer["settingItems"] = true;
781	            }
782	        std::ofstream output(m_state->prompt_requests.string(), std::ios::binary);
783	        output << json{{"settingItems", items}, {"cases", recorded}}.dump(1) << '\n';
784	        check(output.good(), "prompt_requests_written");
785	        finish();
786	    }
