#!/usr/bin/env python3
"""Puts the points of single-point recordings into a whole recording, and
builds settingItems again as the recorder does (record_prompt_requests).
Usage: merge_points.py whole.json out.json single.json...
With no single files it only round-trips whole.json (a check that this
script writes the recorder's bytes)."""
import json
import sys


def compact(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def expand(recording):
    """Each case with its setting items in place of their indexes."""
    items = recording["settingItems"]
    cases = recording["cases"]
    for kept in cases.values():
        for answer in kept["answers"]:
            if not answer.pop("settingItems", False):
                continue
            output = json.loads(answer["output"])
            for field in ("items", "unknownKeys"):
                if field in output["result"]:
                    output["result"][field] = [items[i] for i in output["result"][field]]
            answer["output"] = output
    return cases


whole = json.load(open(sys.argv[1]))
cases = expand(whole)
for path in sys.argv[3:]:
    single = expand(json.load(open(path)))
    assert len(single) == 1, path
    cases.update(single)

items, index = [], {}
for name in sorted(cases):
    for answer in cases[name]["answers"]:
        if answer["tool"] not in ("settings_get", "settings_search"):
            continue
        output = answer["output"]
        if isinstance(output, str):
            output = json.loads(output)
        for field in ("items", "unknownKeys"):
            if field not in output["result"]:
                continue
            for n, item in enumerate(output["result"][field]):
                key = compact(item)
                if key not in index:
                    index[key] = len(items)
                    items.append(item)
                output["result"][field][n] = index[key]
        answer["output"] = compact(output)
        answer["settingItems"] = True

with open(sys.argv[2], "w", encoding="utf-8") as f:
    f.write(json.dumps({"cases": cases, "settingItems": items}, ensure_ascii=False, sort_keys=True, indent=1) + "\n")

