#!/usr/bin/env python3
"""Differences between two recordings, per point, after replacing what
differs between any two runs: timestamps, temporary folders, picture bytes.
Usage: compare.py a.json b.json"""
import json
import re
import sys

NOISE = [
    (re.compile(r"\d{4}-\d\d-\d\dT[\d:.]+Z"), "<time>"),
    (re.compile(r"jusprin-shell-[0-9A-Za-z-]+"), "<tmp>"),
    (re.compile(r"/var/folders/[^\"\\ ]+"), "<tmp>"),
    (re.compile(r"data:image/png;base64,[A-Za-z0-9+/=]+"), "<png>"),
    (re.compile(r"\\\"bytes\\\":\d+|\"bytes\":\d+"), "<bytes>"),
]


def expand(path):
    recording = json.load(open(path))
    items = recording["settingItems"]
    out = {}
    for name, kept in recording["cases"].items():
        for answer in kept["answers"]:
            output = json.loads(answer["output"])
            if answer.get("settingItems"):
                for field in ("items", "unknownKeys"):
                    if field in output["result"]:
                        output["result"][field] = [items[i] for i in output["result"][field]]
            answer["output"] = output
        for item in kept["body"]["input"]:
            if item.get("type") == "function_call_output":
                item["output"] = json.loads(item["output"])
        text = json.dumps(kept, sort_keys=True, ensure_ascii=False)
        for pattern, repl in NOISE:
            text = pattern.sub(repl, text)
        out[name] = json.loads(text)
    return out


def leaves(value, path=""):
    if isinstance(value, dict):
        for k, v in value.items():
            yield from leaves(v, f"{path}/{k}")
    elif isinstance(value, list):
        for i, v in enumerate(value):
            yield from leaves(v, f"{path}/{i}")
    else:
        yield path, value


a, b = expand(sys.argv[1]), expand(sys.argv[2])
print("points:", len(a), len(b), "only in one:", sorted(set(a) ^ set(b)))
total = 0
for name in sorted(set(a) & set(b)):
    if a[name] == b[name]:
        continue
    la, lb = dict(leaves(a[name])), dict(leaves(b[name]))
    diff = [(p, la.get(p), lb.get(p)) for p in sorted(set(la) | set(lb)) if la.get(p) != lb.get(p)]
    total += len(diff)
    print(f"{name}: {len(diff)} differing leaves, answers {len(a[name]['answers'])} vs {len(b[name]['answers'])}")
    for p, x, y in diff[:8]:
        print("   ", p, "|", str(x)[:90], "|", str(y)[:90])
print("total differing leaves:", total)

